CREATE VIEW dbo.IV_Q$DEMO_EQUIP_JD ( SeqPessoa, Pessoa, SeqQuestionario, SeqFormulario, Formulario, DtaRealizacao, UsuInclusao, DtaAlteracao, UsuAlteracao,  Observacao, SeqHistorico, Resultado, Processo, Departamento, LinkDocto, LinkNro, LinkSerie , DEMO_JD_MODELO, DEMO_JD_CLIENTE, DEMO_JD_USO, DEMO_JD_ESP_CSC, DEMO_JD_CHASSI, DEMO_JD_VALOR_DEMO, DEMO_JD_QTDE_NEGOC, DEMO_JD_OBJ_DEMO, DEMO_JD_ENDERECO, DEMO_JD_CULTURA, DEMO_JD_DATA, DEMO_JD_RESPONSAVEL, DEMO_JD_CONTATO_RESP, DEMO_JD_EMAIL_RESP, DEMO_JD_OPERACAO, DEMO_JD_IMPLEMENTO, DEMO_JD_HORIMET_INIC, DEMO_JD_HORIM_FINAL, DEMO_JD_DIESEL_GASTO, DEMO_JD_NIVEL_TANQUE, DEMO_JD_AREA_TRAB, DEMO_JD_DEPOIMENTO)    AS SELECT TBASE.SEQPESSOA, TBASE.NOMERAZAO, QST.SEQQUESTIONARIO, FRM.SEQFORMULARIO, FRM.DESCRICAO, QST.DTAREALIZACAO, QST.USUINCLUSAO, QST.DTAALTERACAO, QST.USUALTERACAO, QST.OBS, QST.SEQHISTORICO, QST.RESULTADO, QST.PROCESSO, QST.DEPARTAMENTO, QST.LINKDOCTO, QST.LINKNRO, QST.LINKSERIE , TABF.DEMO_JD_MODELO, TABF.DEMO_JD_CLIENTE, TABF.DEMO_JD_USO, TABF.DEMO_JD_ESP_CSC, TABF.DEMO_JD_CHASSI, TABF.DEMO_JD_VALOR_DEMO, TABF.DEMO_JD_QTDE_NEGOC, TABF.DEMO_JD_OBJ_DEMO, TABF.DEMO_JD_ENDERECO, TABF.DEMO_JD_CULTURA, TABF.DEMO_JD_DATA, TABF.DEMO_JD_RESPONSAVEL, TABF.DEMO_JD_CONTATO_RESP, TABF.DEMO_JD_EMAIL_RESP, TABF.DEMO_JD_OPERACAO, TABF.DEMO_JD_IMPLEMENTO, TABF.DEMO_JD_HORIMET_INIC, TABF.DEMO_JD_HORIM_FINAL, TABF.DEMO_JD_DIESEL_GASTO, TABF.DEMO_JD_NIVEL_TANQUE, TABF.DEMO_JD_AREA_TRAB, TABF.DEMO_JD_DEPOIMENTO   FROM IV_Q_DEMO_EQUIP_JD TABF 	JOIN IV_QUESTIONARIO QST ON QST.SEQQUESTIONARIO =  TABF.SEQQUESTIONARIO 	JOIN IV_FORMULARIO FRM ON   FRM.SEQFORMULARIO = QST.SEQFORMULARIO 	JOIN GE_PESSOA TBASE ON TBASE.SEQPESSOA = QST.SEQPESSOA  